package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, k int
	var l int64
	fmt.Fscan(in, &n, &k, &l)

	maxN := 2*n + 1
	fact := make([]int64, maxN+1)
	invFact := make([]int64, maxN+1)

	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	invFact[maxN] = modPow(fact[maxN], mod-2)
	for i := maxN; i >= 1; i-- {
		invFact[i-1] = invFact[i] * int64(i) % mod
	}

	comb := func(a, b int) int64 {
		if b < 0 || b > a {
			return 0
		}
		return fact[a] * invFact[b] % mod * invFact[a-b] % mod
	}

	pow2 := make([]int64, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = pow2[i-1] * 2 % mod
	}

	var answer int64
	commonDenominator := invFact[2*n+1]

	for i := k; i <= n; i++ {
		var inner int64
		for j := 0; j <= n-i; j++ {
			a := i + 2*j
			b := 2*n - i - 2*j

			term := comb(n-i, j)
			term = term * fact[a] % mod
			term = term * fact[b] % mod
			inner += term
			if inner >= mod {
				inner -= mod
			}
		}

		term := comb(n, i) * pow2[i] % mod
		term = term * inner % mod
		term = term * commonDenominator % mod

		answer += term
		if answer >= mod {
			answer -= mod
		}
	}

	answer = answer * (l % mod) % mod

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

